import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State, Watch } from '@stencil/core';
import { FabSize, FabVariant, IconPosition, Rel, Target } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';
import { FocusHelper } from '../../utils/focus-helper';
import { IconSizeHelper } from '../../utils/icon-size-helper';
import { verifyTarget } from '../../utils/link-helper';

@Component({
  tag: 'groupui-floating-action-button',
  styleUrl: 'floating-action-button.scss',
  shadow: { delegatesFocus: true },
})
export class FloatingActionButton {
  /**
   * variant of the button
   */
  @Prop({ reflect: true }) readonly variant: FabVariant = 'primary';

  /**
   * deactivates the button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * sets the button size
   */
  @Prop({ reflect: true }) readonly size: FabSize = 'm';

  /**
   * hide text content and only show the icon. requires an icon to be set
   */
  @Prop({ reflect: true }) readonly iconOnly: boolean = false;

  /**
   * icon name e.g. 'clock-24'. Use the following matching icon sizes for the different button sizes: m: 24px l: 32px
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * position of the icon
   */
  @Prop({ reflect: true }) readonly iconPosition: IconPosition = 'left';

  /**
   * URL that the hyperlink points to. Examples: https://www.volkswagen.de/ - tel:05361/12345 - mailto:john.doe@example.com - #anchor1<br><br>
   **/
  @Prop({ reflect: true }) readonly url: string;

  /**
   * where to display the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * in which relation is the linked URL to the current page
   */
  @Prop({ reflect: true }) readonly rel: Rel;

  /**
   * aria label of the button to pass accessibility criteria.
   */
  @Prop({ reflect: true }) readonly label: string = 'floating-action-button';

  /**
   * sets focus automatically
   */
  // eslint-disable-next-line @stencil-community/reserved-member-names
  @Prop({ reflect: true }) readonly autofocus: boolean = false;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false, composed: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() tabIndex: number = 0;

  @State() backupTabIndex: number;

  private ariaAttributes: AriaAttributes;

  @Watch('disabled')
  handleDisabledChanged() {
    try {
      if (this.disabled) {
        this.backupTabIndex = this.tabIndex;
      }
      this.tabIndex = FocusHelper.handleHostTabIndex(this.disabled, this.backupTabIndex);
      this.host.shadowRoot.getElementById('button').blur();
    } catch (event) {}
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  @Watch('size')
  onSizeChanged() {
    IconSizeHelper.setHeightAndWidth({
      host: this.host,
      size: this.size,
      selector: 'groupui-icon',
    });
  }

  componentDidLoad() {
    IconSizeHelper.setHeightAndWidth({
      host: this.host,
      size: this.size,
      selector: 'groupui-icon',
    });
    this.autofocus && this.host.focus && this.host.focus();
    this.groupuiDidLoad.emit();
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.backupTabIndex = Number(this.host.getAttribute('tabindex'));
    this.tabIndex = FocusHelper.handleHostTabIndex(this.disabled, this.backupTabIndex);
  }

  private getSlotAndIcon() {
    if (this.icon || this.iconSource) {
      if (this.iconOnly) {
        return this.getIcon(true);
      }
      if (this.iconPosition === 'left') {
        return [this.getIcon(), <slot />];
      }
      if (this.iconPosition === 'right') {
        return [<slot />, this.getIcon()];
      }
    } else {
      return <slot />;
    }
  }

  private getIcon(iconOnly: boolean = false) {
    if (iconOnly) {
      return <groupui-icon name={this.icon} src={this.iconSource} />;
    }
    return <groupui-icon class={'icon-' + this.iconPosition} name={this.icon} src={this.iconSource} />;
  }

  render() {
    return (
      <Host>
        {this.url ? (
          <a tabindex="-1" href={this.url} target={verifyTarget(this.target)} rel={this.rel}>
            <button tabIndex={this.tabIndex} {...this.ariaAttributes} id="button" role="link">
              {this.getSlotAndIcon()}
            </button>
          </a>
        ) : (
          <button id="button" role="button" tabIndex={this.tabIndex} {...this.ariaAttributes}>
            {this.getSlotAndIcon()}
          </button>
        )}
      </Host>
    );
  }
}
